        ("struct", rest)
    } else if let Some(rest) = trimmed.strip_prefix("typedef enum ") {
        ("enum", rest)
    } else if let Some(rest) = c_like_function_name(trimmed) {
        ("function", rest)
    } else if let Some(rest) = trimmed.strip_prefix("pub async fn ") {
