    fn from_chunks_with_semantic_config(
        semantic_config: Option<EncoderSpec>,
        chunks: Vec<Chunk>,
    ) -> Result<Self> {
        if chunks.is_empty() {
            bail!("No supported files found.");
        }
        let bm25_index = Bm25Index::build_from_chunks(&chunks);
        let (file_mapping, language_mapping, symbol_mapping) = populate_mapping(&chunks);
        Ok(Self {
            bm25_index,
            semantic_state: Mutex::new(None),
            semantic_config,
            chunks,
            file_mapping,
            language_mapping,
            symbol_mapping,
            search_cache: Mutex::new(HashMap::new()),
