        };
        write_message(
            &mut stdout,
            &json!({"jsonrpc": "2.0", "id": id, "result": result}),
            incoming.framing,
        )?;
    }
    Ok(())
}

fn negotiated_protocol_version(message: &Value) -> &'static str {
    let requested = message
        .get("params")
        .and_then(|params| params.get("protocolVersion"))
        .and_then(Value::as_str);
    requested
        .and_then(|version| {
            SUPPORTED_PROTOCOL_VERSIONS
                .iter()
                .copied()
                .find(|supported| *supported == version)
        })
        .unwrap_or(DEFAULT_PROTOCOL_VERSION)
}

struct IndexCache {
    indexes: HashMap<String, SifsIndex>,
    model_options: ModelOptions,
    cache_config: CacheConfig,
    offline: bool,
}

impl Default for IndexCache {
    fn default() -> Self {
        Self::new(ModelOptions::default(), CacheConfig::default(), false)
    }
}

impl IndexCache {
    fn new(model_options: ModelOptions, cache_config: CacheConfig, offline: bool) -> Self {
        Self {
            indexes: HashMap::new(),
            model_options,
            cache_config,
            offline,
        }
    }

    fn source_key(source: &str, ref_name: Option<&str>) -> Result<String> {
        let source_key = if is_git_url(source) {
            ref_name
                .map(|r| format!("{source}@{r}"))
                .unwrap_or_else(|| source.to_owned())
        } else {
            Path::new(source)
                .canonicalize()?
                .to_string_lossy()
                .to_string()
        };
        Ok(source_key)
    }

    fn key_for(source: &str, ref_name: Option<&str>, options: &McpIndexOptions) -> Result<String> {
        Ok(format!(
            "{}|{}",
            Self::source_key(source, ref_name)?,
            options.cache_key()
        ))
    }

    fn get(
        &mut self,
        source: &str,
        ref_name: Option<&str>,
        options: &McpIndexOptions,
    ) -> Result<&SifsIndex> {
        let key = Self::key_for(source, ref_name, options)?;
        if !self.indexes.contains_key(&key) {
            let source_key = Self::source_key(source, ref_name)?;
            let index = self.build_index(source, ref_name, &source_key, options)?;
            self.indexes.insert(key.clone(), index);
        } else if self
            .indexes
            .get(&key)
            .and_then(SifsIndex::is_fresh)
            .is_some_and(|fresh| !fresh)
        {
            self.refresh(source, ref_name, options)?;
        }
        Ok(self.indexes.get(&key).unwrap())
    }

    fn refresh(
        &mut self,
        source: &str,
        ref_name: Option<&str>,
        options: &McpIndexOptions,
    ) -> Result<&SifsIndex> {
        let key = Self::key_for(source, ref_name, options)?;
        let source_key = Self::source_key(source, ref_name)?;
        let index = self.build_index(source, ref_name, &source_key, options)?;
        self.indexes.insert(key.clone(), index);
        Ok(self.indexes.get(&key).unwrap())
    }

    fn build_index(
        &self,
        source: &str,
        ref_name: Option<&str>,
        source_key: &str,
        options: &McpIndexOptions,
    ) -> Result<SifsIndex> {
        let index = if is_git_url(source) {
            if self.offline || options.offline {
                anyhow::bail!("--offline does not allow remote Git sources");
            }
            SifsIndex::from_git_with_index_options(source, ref_name, options.index_options())?
        } else {
            SifsIndex::from_path_with_index_options(source_key, options.index_options())?
        };
        Ok(index)
    }

    fn remove(&mut self, source: &str, ref_name: Option<&str>) -> Result<bool> {
        let source_key = Self::source_key(source, ref_name)?;
        let prefix = format!("{source_key}|");
        let original_len = self.indexes.len();
        self.indexes
            .retain(|key, _| key != &source_key && !key.starts_with(&prefix));
        Ok(self.indexes.len() != original_len)
    }

    fn contains_source(&self, source: &str, ref_name: Option<&str>) -> bool {
        Self::source_key(source, ref_name)
            .map(|source_key| {
                let prefix = format!("{source_key}|");
                self.indexes
                    .keys()
                    .any(|key| key == &source_key || key.starts_with(&prefix))
            })
            .unwrap_or(false)
    }

    fn keys(&self) -> Vec<String> {
        let mut keys: Vec<_> = self.indexes.keys().cloned().collect();
        keys.sort();
        keys
    }

    fn daemon_search(
        &self,
        source: &str,
        ref_name: Option<&str>,
        query: &str,
        options: &SearchOptions,
        index_options: &McpIndexOptions,
    ) -> Option<crate::daemon::protocol::SearchResultSet> {
        let paths = default_daemon_paths().ok()?;
        if !paths.socket.exists() {
            return None;
        }
        let source = SourceSpec::resolve(
            source,
            ref_name.map(str::to_owned),
            self.offline || index_options.offline,
        )
        .ok()?;
        let runtime_options = index_options.runtime_options(options.mode);
        match DaemonClient::new(paths).send(DaemonRequest::Search {
            source,
            options: runtime_options,
            query: query.to_owned(),

Chunk ID: 1d6ba2
Wall time: 0.0000 seconds
Process exited with code 0
Original token count: 3165
Output:
            query: query.to_owned(),
            search: SearchOptionsWire::from(options.clone()),
        }) {
            Ok(DaemonResult::Search(result)) => Some(result),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
struct McpIndexOptions {
    encoder_spec: EncoderSpec,
    cache_config: CacheConfig,
    offline: bool,
    include_docs: bool,
    extensions: Option<Vec<String>>,
}

impl McpIndexOptions {
    fn from_cache(cache: &IndexCache, profile: Option<&profiles::Profile>) -> Self {
        let offline = cache.offline || profile.and_then(|profile| profile.offline).unwrap_or(false);
        let no_download = profile
            .and_then(|profile| profile.no_download)
            .unwrap_or(false);
        let policy = if offline {
            ModelLoadPolicy::Offline
        } else if no_download {
            ModelLoadPolicy::NoDownload
        } else {
            cache.model_options.policy
        };
        let model = profile
            .and_then(|profile| profile.model.as_deref())
            .unwrap_or(cache.model_options.model.as_str());
        let encoder_spec = match profile
            .and_then(|profile| profile.encoder.as_deref())
            .unwrap_or("model2vec")
        {
            "hashing" => EncoderSpec::hashing(),
            _ => EncoderSpec::model2vec(Some(model), policy),
        };
        let cache_config = profile
            .and_then(|profile| {
                if profile.no_cache.unwrap_or(false) {
                    Some(CacheConfig::Disabled)
                } else if profile.project_cache.unwrap_or(false) {
                    Some(CacheConfig::Project)
                } else {
                    profile.cache_dir.clone().map(CacheConfig::Custom)
                }
            })
            .unwrap_or_else(|| cache.cache_config.clone());
        let include_docs = profile
            .and_then(|profile| profile.include_docs)
            .unwrap_or(false);
        let extensions = normalized_extensions(
            profile
                .and_then(|profile| profile.extensions.as_deref())
                .unwrap_or(&[]),
        );
        Self {
            encoder_spec,
            cache_config,
            offline,
            include_docs,
            extensions,
        }
    }

    fn index_options(&self) -> IndexOptions {
        IndexOptions::new(match &self.encoder_spec {
            EncoderSpec::Model2Vec(options) => options.clone(),
            EncoderSpec::Hashing { .. } => ModelOptions::default(),
        })
        .with_encoder_spec(self.encoder_spec.clone())
        .with_cache(self.cache_config.clone())
        .with_include_text_files(self.include_docs)
        .with_extensions(self.extension_set())
    }

    fn runtime_options(&self, mode: SearchMode) -> IndexRuntimeOptions {
        let mut options = match mode {
            SearchMode::Bm25 => IndexRuntimeOptions::sparse(self.cache_config.clone()),
            SearchMode::Semantic | SearchMode::Hybrid => IndexRuntimeOptions::with_encoder(
                self.encoder_spec.clone(),
                self.cache_config.clone(),
            ),
        };
        options.include_text_files = self.include_docs;
        options.extensions = self.extensions.clone();
        options
    }

    fn extension_set(&self) -> Option<HashSet<String>> {
        self.extensions
            .as_ref()
            .map(|values| values.iter().cloned().collect())
    }

    fn cache_key(&self) -> String {
        format!(
            "encoder={:?};cache={:?};include_docs={};extensions={}",
            self.encoder_spec,
            self.cache_config,
            self.include_docs,
            self.extensions
                .as_ref()
                .map(|values| values.join(","))
                .unwrap_or_default()
        )
    }
}

fn handle_tool_call(
    message: &Value,
    cache: &mut IndexCache,
    default_source: Option<&str>,
    ref_name: Option<&str>,
) -> Value {
    let params = message.get("params").cloned().unwrap_or_default();
    let name = params
        .get("name")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let args = params
        .get("arguments")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let tool_result = match name {
        "search" => tool_search(args, cache, default_source, ref_name),
        "find_related" => tool_find_related(args, cache, default_source, ref_name),
        "index_status" => tool_index_status(args, cache, default_source, ref_name),
        "refresh_index" => tool_refresh_index(args, cache, default_source, ref_name),
        "clear_index" => tool_clear_index(args, cache, default_source, ref_name),
        "list_files" => tool_list_files(args, cache, default_source, ref_name),
        "get_chunk" => tool_get_chunk(args, cache, default_source, ref_name),
        "agent_context" => tool_agent_context(),
        "profile_list" => tool_profile_list(),
        "profile_show" => tool_profile_show(args),
        "feedback_create" => tool_feedback_create(args),
        "feedback_list" => tool_feedback_list(args),
        "agent_print" => tool_agent_print(args),
        "agent_doctor" => tool_agent_doctor(args),
        "init_agent" => tool_init_agent(args),
        _ => ToolText::error(format!("Unknown tool: {name}")),
    };
    let mut result = json!({"content": [{"type": "text", "text": tool_result.text}]});
    if let Some(structured) = tool_result.structured {
        result["structuredContent"] = structured;
    }
    if tool_result.is_error {
        result["isError"] = json!(true);
    }
    result
}

struct ToolText {
    text: String,
    structured: Option<Value>,
    is_error: bool,
}

impl ToolText {
    fn ok(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            structured: None,
            is_error: false,
        }
    }

    fn ok_structured(text: impl Into<String>, structured: Value) -> Self {
        Self {
            text: text.into(),
            structured: Some(structured),
            is_error: false,
        }
    }

    fn error(text: impl Into<String>) -> Self {
        Self {
            text: text.into(),
            structured: None,
            is_error: true,
        }
    }
}

fn tool_search(
    args: Value,
    cache: &mut IndexCache,
    default_source: Option<&str>,
    ref_name: Option<&str>,
) -> ToolText {
    let query = args
        .get("query")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let source = match selected_source(&args, default_source) {
        Ok(Some(source)) => source,
        Ok(None) => return ToolText::error(no_repo_message()),
        Err(message) => return ToolText::error(message),
    };
    let profile = match selected_profile(&args) {
        Ok(profile) => profile,
        Err(message) => return ToolText::error(message),
    };
    let mode = match parse_mcp_mode(&args, profile.as_ref()) {
        Ok(mode) => mode,
        Err(message) => return ToolText::error(message),
    };
    let top_k = match parse_mcp_limit(&args, "limit", profile.as_ref().and_then(|p| p.limit), 5) {
        Ok(limit) => limit,
        Err(message) => return ToolText::error(message),
    };
    let options = match search_options_from_args(&args, top_k, mode) {
        Ok(options) => options,
        Err(message) => return ToolText::error(message),
    };
    let index_options = McpIndexOptions::from_cache(cache, profile.as_ref());
    if let Some(result) = cache.daemon_search(&source, ref_name, query, &options, &index_options) {
        return mcp_search_result(McpSearchPresentation {
            source: &source,
            query,
            mode,
            top_k,
            options: &options,
            stats: result.stats,
            warnings: json!([]),
            fresh: None,
            results: result.results,
        });
    }
    match cache.get(&source, ref_name, &index_options) {
        Ok(index) => {
            let results = match index.search_with(query, &options) {
                Ok(results) => results,
                Err(err) => return ToolText::error(format!("Search failed: {err}")),
            };
            mcp_search_result(McpSearchPresentation {
                source: &source,
                query,
                mode,
                top_k,
                options: &options,
                stats: index.stats(),
                warnings: search_warnings_json(index, &options),
                fresh: index.is_fresh(),
                results,
            })
        }
        Err(err) => ToolText::error(format!("Failed to index {source:?}: {err}")),
    }
}

struct McpSearchPresentation<'a> {
    source: &'a str,
    query: &'a str,
    mode: SearchMode,
    top_k: usize,
    options: &'a SearchOptions,
    stats: crate::IndexStats,
    warnings: Value,
    fresh: Option<bool>,
    results: Vec<crate::SearchResult>,
}

fn mcp_search_result(presentation: McpSearchPresentation<'_>) -> ToolText {
    let structured = json!({
        "source": presentation.source,
        "mode": presentation.mode.to_string(),
        "limit": presentation.top_k,
        "alpha": presentation.options.alpha,
        "filter_languages": presentation.options.filter_languages,
        "filter_paths": presentation.options.filter_paths,
        "stats": presentation.stats,
        "fresh": presentation.fresh,
        "warnings": presentation.warnings,
        "truncated": presentation.results.len() >= presentation.top_k,
        "hint": if presentation.results.len() >= presentation.top_k { Some("Increase limit or add filter_languages/filter_paths to narrow the search.") } else { None },
        "results": structured_results(&presentation.results),
    });
    if presentation.results.is_empty() {
        ToolText::ok_structured(no_results_message(), structured)
    } else {
        ToolText::ok_structured(
            format_results(
                &format!(
                    "Search results for: {:?} (mode={})",
                    presentation.query, presentation.mode
                ),
                &presentation.results,
            ),
            structured,
        )
    }
}

fn tool_find_related(
    args: Value,
    cache: &mut IndexCache,
    default_source: Option<&str>,
    ref_name: Option<&str>,
) -> ToolText {
    let file_path = args
        .get("file_path")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let line = args.get("line").and_then(Value::as_u64).unwrap_or(0) as usize;
    let source = match selected_source(&args, default_source) {
        Ok(Some(source)) => source,
        Ok(None) => return ToolText::error(no_repo_message()),
        Err(message) => return ToolText::error(message),
    };
    let profile = match selected_profile(&args) {
        Ok(profile) => profile,
        Err(message) => return ToolText::error(message),
    };
    let top_k = match parse_mcp_limit(&args, "limit", profile.as_ref().and_then(|p| p.limit), 5) {
        Ok(limit) => limit,
        Err(message) => return ToolText::error(message),
    };
    let index_options = McpIndexOptions::from_cache(cache, profile.as_ref());
    match cache.get(&source, ref_name, &index_options) {
        Ok(index) => {
            let Some(chunk) = resolve_chunk(&index.chunks, file_path, line) else {
                return ToolText::ok(format!(
                    "No chunk found at {file_path}:{line}. Make sure the file is indexed and the line number is within a known chunk."
                ));
            };
            let results = match index.find_related(&chunk, top_k) {
                Ok(results) => results,
                Err(err) => return ToolText::error(format!("find_related failed: {err}")),
            };
            let structured = json!({
                "source": source,
                "file_path": file_path,
                "line": line,
                "stats": index.stats(),
                "warnings": index_warnings(index),
                "results": structured_results(&results),
            });
            if results.is_empty() {
                ToolText::ok_structured(
                    format!("No related chunks found for {file_path}:{line}."),
                    structured,
                )
            } else {
                ToolText::ok_structured(
                    format_results(&format!("Chunks related to {file_path}:{line}"), &results),
                    structured,
                )
            }
        }
        Err(err) => ToolText::error(format!("Failed to index {source:?}: {err}")),
    }
}

