            Some(ref_name) => format!("{}@{}", self.source, ref_name),
            None => self.source.clone(),
        }
    }

    pub fn as_path(&self) -> Option<&Path> {
        matches!(self.kind, SourceKind::LocalPath).then(|| Path::new(&self.source))
