#[allow(clippy::too_many_arguments)]
fn build_index_for_mode(
    path: &str,
    ref_name: Option<&str>,
    mode: SearchMode,
    encoder_spec: EncoderSpec,
    cache: CacheConfig,
    offline: bool,
    include_docs: bool,
    extensions: Option<std::collections::HashSet<String>>,
) -> Result<SifsIndex> {
    match mode {
        SearchMode::Bm25 => {
            build_sparse_index(path, ref_name, cache, offline, include_docs, extensions)
        }
        SearchMode::Semantic | SearchMode::Hybrid => build_hybrid_index(
            path,
            ref_name,
            encoder_spec,
            cache,
            offline,
            include_docs,
            extensions,
        ),
    }
}

fn build_sparse_index(
    path: &str,
    ref_name: Option<&str>,
    cache: CacheConfig,
    offline: bool,
    include_docs: bool,
    extensions: Option<std::collections::HashSet<String>>,
) -> Result<SifsIndex> {
    let options = IndexOptions::sparse()
        .with_cache(cache)
        .with_include_text_files(include_docs)
        .with_extensions(extensions);
    if is_git_url(path) {
        if offline {
            bail!("--offline does not allow remote Git sources");
        }
        SifsIndex::from_git_with_index_options(path, ref_name, options)
    } else {
        SifsIndex::from_path_with_index_options(path, options)
    }
}

fn build_hybrid_index(
    path: &str,
    ref_name: Option<&str>,
    encoder_spec: EncoderSpec,
    cache: CacheConfig,
    offline: bool,
    include_docs: bool,
    extensions: Option<std::collections::HashSet<String>>,
) -> Result<SifsIndex> {
    let options = IndexOptions::sparse()
        .with_encoder_spec(encoder_spec)
        .with_cache(cache)
        .with_include_text_files(include_docs)
        .with_extensions(extensions);
    if is_git_url(path) {
        if offline {
            bail!("--offline does not allow remote Git sources");
        }
        SifsIndex::from_git_with_index_options(path, ref_name, options)
    } else {
        SifsIndex::from_path_with_index_options(path, options)
    }
}

fn extension_set(values: &[String]) -> Option<std::collections::HashSet<String>> {
    normalized_extensions(values).map(|values| values.into_iter().collect())
}

fn cache_config(cache_dir: Option<PathBuf>, no_cache: bool, project_cache: bool) -> CacheConfig {
    if no_cache {
        CacheConfig::Disabled
    } else if project_cache {
        CacheConfig::Project
    } else if let Some(path) = cache_dir {
        CacheConfig::Custom(path)
    } else {
        CacheConfig::Platform
    }
}

fn run_files(resolved: &ResolvedInvocation, limit: usize, output: OutputArgs) -> Result<()> {
    if let Some(DaemonResult::ListFiles {
        source,
        total,
        files,
    }) = try_daemon_list_files(resolved, limit)?
    {
        print_files_output(&source.source, total, limit, 0, files, output)?;
        return Ok(());
    }
    let policy = model_policy(resolved.offline, resolved.no_download);
    let started = Instant::now();
    let index = build_hybrid_index(
        &resolved.source,
        resolved.ref_name.as_deref(),
        encoder_spec(resolved.encoder, resolved.model.as_deref(), policy),
        resolved.cache.clone(),
        resolved.offline,
        resolved.include_docs,
        extension_set(&resolved.extensions),
    )?;
    let elapsed_ms = started.elapsed().as_millis();
    let files = index.indexed_files();
    let shown: Vec<_> = files.iter().take(limit).cloned().collect();
    print_files_output(
        &resolved.source,
        files.len(),
        limit,
        elapsed_ms,
        shown,
        output,
    )
}

fn print_files_output(
    source: &str,
    total: usize,
    limit: usize,
    elapsed_ms: u128,
    shown: Vec<String>,
    output: OutputArgs,
) -> Result<()> {
    let payload = json!({
        "source": source,
        "total": total,
        "limit": limit,
        "truncated": total > shown.len(),
        "hint": if total > shown.len() { Some("Increase --limit or narrow by source to inspect more indexed files.") } else { None },
        "elapsed_ms": elapsed_ms,
        "files": shown,
    });
    if output.json {
        println!("{}", serde_json::to_string_pretty(&payload)?);
    } else if output.jsonl {
        for file in &shown {
            println!(
                "{}",
                serde_json::to_string(&json!({
                    "source": source,
                    "total": total,
                    "limit": limit,
                    "file_path": file,
                }))?
            );
        }
    } else {
        match output.format {
            TextFormat::Human => {
                println!(
                    "Indexed files for {source:?} (showing {} of {}):",
                    shown.len(),
                    total
                );
                for file in shown {
                    println!("{file}");
                }
            }
            TextFormat::Compact => {
                for file in shown {
                    println!("{file}");
                }
            }
        }
    }
    Ok(())
}

