        resolved.ref_name.as_deref(),
        resolved.cache.clone(),
        resolved.offline,
        resolved.include_docs,
        extension_set(&resolved.extensions),
    )?;
    let all_postings = index.symbol_lookup(name, usize::MAX);
    let (total, postings) =
