            log_file: runtime_dir.join("sifs.log"),
            runtime_dir: runtime_dir.clone(),
        };

        paths.ensure_runtime_dir().unwrap();

        let mode = std::fs::metadata(runtime_dir).unwrap().permissions().mode() & 0o777;
        assert_eq!(mode, 0o700);
    }
}
