fn read_posting_content(source: &str, posting: &sifs::SymbolPosting) -> Option<String> {
    let content = fs::read_to_string(Path::new(source).join(&posting.file_path)).ok()?;
    let lines = content.lines().collect::<Vec<_>>();
    if lines.is_empty() {
        return Some(String::new());
    }
    let start = posting.start_line.saturating_sub(1).min(lines.len());
    let end = posting.end_line.min(lines.len());
    if start >= end {
        return Some(String::new());
    }
    Some(lines[start..end].join("\n"))
}

fn try_daemon_search(
    command: &SearchCommand,
) -> Result<Option<sifs::daemon::protocol::SearchResultSet>> {
    let Some(client) = daemon_client_if_running()? else {
        return Ok(None);
    };
    let source = SourceSpec::resolve(&command.source, command.ref_name.clone(), command.offline)?;
    let policy = model_policy(command.offline, command.no_download);
    let runtime_options = with_index_filters(
        match command.mode {
            SearchMode::Bm25 => IndexRuntimeOptions::sparse(command.cache.clone()),
            SearchMode::Semantic | SearchMode::Hybrid => IndexRuntimeOptions::with_encoder(
                encoder_spec(command.encoder, command.model.as_deref(), policy),
                command.cache.clone(),
            ),
        },
        command.include_docs,
        &command.extensions,
    );
    let mut search = SearchOptions::new(command.limit).with_mode(command.mode);
    search.filter_languages = command.languages.clone();
    search.filter_paths = command.filter_paths.clone();
    search.explain = command.explain;
    match client.send(DaemonRequest::Search {
        source,
        options: runtime_options,
        query: command.query.clone(),
        search: SearchOptionsWire::from(search),
    }) {
        Ok(DaemonResult::Search(results)) => Ok(Some(results)),
        Ok(other) => bail!("unexpected daemon response: {other:?}"),
        Err(_) => Ok(None),
    }
}

fn with_index_filters(
    mut options: IndexRuntimeOptions,
    include_docs: bool,
    extensions: &[String],
) -> IndexRuntimeOptions {
    options.include_text_files = include_docs;
    options.extensions = normalized_extensions(extensions);
    options
}

fn normalized_extensions(values: &[String]) -> Option<Vec<String>> {
    if values.is_empty() {
        return None;
    }
    let mut values = values
        .iter()
        .filter_map(|value| {
            let value = value.trim().trim_start_matches('.').to_lowercase();
            (!value.is_empty()).then(|| format!(".{value}"))
        })
        .collect::<Vec<_>>();
    values.sort();
        }
    }
}

impl NavigationIndex {
    pub fn from_path_with_index_options(
        path: impl AsRef<Path>,
        mut options: IndexOptions,
    ) -> Result<Self> {
        options.semantic_config = None;
        let path = path.as_ref();
        if !path.exists() {
            bail!("Path does not exist: {}", path.display());
        }
        if !path.is_dir() {
            bail!("Path is not a directory: {}", path.display());
        }
        let root = path.canonicalize()?;
        let context = CacheContext::for_source(
            options
                .source_id_override
                .clone()
                .unwrap_or_else(|| format!("path:{}", root.to_string_lossy())),
            &root,
            &options.extensions,
            &options.ignore,
            options.include_text_files,
        );
        let cache_entry = resolve_cache_entry(&options.cache, &root, &context)?;
        let signatures = current_file_signatures(
            &root,
            options.extensions.as_ref(),
            options.ignore.as_ref(),
            options.include_text_files,
        )
        .ok();
        if let (Some(cache_entry), Some(signatures)) = (&cache_entry, &signatures)
            && let Some(payload) = load_cached_navigation_payload(cache_entry, &context, signatures)
        {
            return Ok(Self::from_cached_payload(payload));
        }
        let index = SifsIndex::from_path_with_index_options(&root, options)?;
        Ok(Self::from_sifs_index(&index))
    }

    pub fn from_git_with_index_options(
        url: &str,
        ref_name: Option<&str>,
        options: IndexOptions,
    ) -> Result<Self> {
        let tmp = tempfile::tempdir()?;
        let mut cmd = Command::new("git");
        cmd.arg("clone").arg("--depth").arg("1");
        if let Some(ref_name) = ref_name {
            cmd.arg("--branch").arg(ref_name);
        }
        cmd.arg("--").arg(url).arg(tmp.path());
        let output = cmd.stdin(Stdio::null()).output().context("run git clone")?;
        if !output.status.success() {
            bail!(
                "git clone failed for {url:?}:\n{}",
                String::from_utf8_lossy(&output.stderr).trim()
            );
        }
        let source_id = ref_name
            .map(|name| format!("git:{url}@{name}"))
            .unwrap_or_else(|| format!("git:{url}"));
        Self::from_path_with_index_options(tmp.path(), options.with_source_id(source_id))
    }

    pub fn indexed_files_with_prefix(&self, prefix: Option<&str>, limit: usize) -> Vec<String> {
        let normalized_prefix = prefix
            .map(normalize_filter_path)
            .filter(|prefix| !prefix.is_empty());
        let mut files = self
            .files
            .iter()
            .filter(|file| {
                normalized_prefix
                    .as_ref()
                    .is_none_or(|prefix| file.starts_with(prefix))
            })
            .cloned()
            .collect::<Vec<_>>();
        files.truncate(limit);
        files
    }

