+fn exact_lines_from_chunks(chunks: &[Chunk]) -> HashMap<String, Vec<ExactLinePosting>> {
+    let mut line_values: BTreeMap<(String, usize), ExactLinePosting> = BTreeMap::new();
+    for chunk in chunks {
+        for (offset, line) in chunk.content.lines().enumerate() {
+            let line_number = chunk.start_line + offset;
+            let content = line.trim_end().to_owned();
+            if content.trim().is_empty() {
+                continue;
+            }
+            line_values.entry((chunk.file_path.clone(), line_number)).or_insert_with(|| {
+                ExactLinePosting {
+                    file_path: chunk.file_path.clone(),
+                    line: line_number,
+                    content,
+                    language: chunk.language.clone(),
+                }
+            });
+        }
+    }
+    let mut by_token: HashMap<String, Vec<ExactLinePosting>> = HashMap::new();
+    for posting in line_values.into_values() {
+        let mut tokens = tokenize(&posting.content);
+        tokens.sort();
+        tokens.dedup();
+        for token in tokens {
+            by_token.entry(token).or_default().push(posting.clone());
+        }
+    }
+    by_token
