pub fn walk_files(
    root: &Path,
    extensions: &HashSet<String>,
    ignore: Option<&HashSet<String>>,
) -> Vec<PathBuf> {
    let ignore_owned = ignore.cloned().unwrap_or_default();
    let mut builder = WalkBuilder::new(root);
    builder
        .hidden(true)
        .parents(true)
        .ignore(true)
        .git_ignore(true)
        .git_exclude(true)
        .git_global(true)
        .require_git(false)
        .filter_entry(move |entry| {
            let name = entry.file_name().to_string_lossy();
            let default_name = name.to_lowercase();
            !DEFAULT_IGNORED_DIRS.contains(default_name.as_str())
                && !ignore_owned.contains(name.as_ref())
        });
    let files: Vec<PathBuf> = builder
        .build()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_some_and(|ft| ft.is_file()))
        .map(|entry| entry.into_path())
        .filter(|path| {
            if path
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| DEFAULT_IGNORED_FILES.contains(name.to_lowercase().as_str()))
            {
                return false;
            }
            if path
                .metadata()
                .map(|metadata| metadata.len() > DEFAULT_MAX_FILE_BYTES)
                .unwrap_or(false)
            {
                return false;
            }
            path.extension()
                .map(|ext| {
                    extensions
                        .contains(format!(".{}", ext.to_string_lossy().to_lowercase()).as_str())
                })
                .unwrap_or(false)
        })
        .collect();
    let mut files = files;
    files.sort();
    files
}

