fn print_files_output(
    source: &str,
    total: usize,
    prefix: Option<&str>,
    limit: usize,
    elapsed_ms: u128,
    shown: Vec<String>,
    output: OutputArgs,
) -> Result<()> {
    let payload = json!({
        "source": source,
        "total": total,
        "prefix": prefix,
        "limit": limit,
        "truncated": total > shown.len(),
        "hint": if total > shown.len() { Some("Increase --limit or narrow by source to inspect more indexed files.") } else { None },
        "elapsed_ms": elapsed_ms,
        "files": shown,
    });
    if output.json {
        println!("{}", serde_json::to_string_pretty(&payload)?);
    } else if output.jsonl {
        for file in &shown {
            println!(
                "{}",
                serde_json::to_string(&json!({
                    "source": source,
                    "total": total,
                    "prefix": prefix,
                    "limit": limit,
                    "truncated": total > shown.len(),
                    "file_path": file,
                }))?
            );
        }
    } else {
        match output.format {
            TextFormat::Human => {
                println!(
                    "Indexed files for {source:?} (showing {} of {}):",
                    shown.len(),
                    total
                );
                for file in shown {
                    println!("{file}");
                }
            }
            TextFormat::Compact => {
                for file in shown {
                    println!("{file}");
                }
            }
        }
    }
    Ok(())
}

fn try_daemon_list_files(
    resolved: &ResolvedInvocation,
    prefix: Option<&str>,
    limit: usize,
) -> Result<Option<sifs::daemon::protocol::DaemonResult>> {
    let Some(client) = daemon_client_if_running()? else {
        return Ok(None);
    };
    let source = SourceSpec::resolve(
        &resolved.source,
        resolved.ref_name.clone(),
        resolved.offline,
    )?;
    match client.send(DaemonRequest::ListFiles {
        source,
        options: with_index_filters(
            IndexRuntimeOptions::sparse(resolved.cache.clone()),
            resolved.include_docs,
            &resolved.extensions,
        ),
        limit,
        prefix: prefix.map(str::to_owned),
    }) {
        Ok(result @ DaemonResult::ListFiles { .. }) => Ok(Some(result)),
        Ok(other) => bail!("unexpected daemon response: {other:?}"),
        Err(_) => Ok(None),
    }
}

