fn append_literal_line_matches(
    results: &mut Vec<SearchResult>,
    seen: &mut HashSet<(String, usize)>,
    source: &str,
    query: &str,
    files: &[String],
    limit: usize,
) {
    for file in files {
        if results.len() >= limit {
            break;
        }
        let Ok(content) = fs::read_to_string(Path::new(source).join(file)) else {
            continue;
        };
        let language = sifs::file_walker::language_for_path(Path::new(file)).map(str::to_owned);
        for (idx, line) in content.lines().enumerate() {
            if results.len() >= limit {
                break;
            }
            if !line.contains(query) {
                continue;
            }
            let line_number = idx + 1;
            if !seen.insert((file.clone(), line_number)) {
                continue;
            }
            let rank = results.len();
            results.push(SearchResult {
                chunk: Chunk {
                    content: line.to_owned(),
                    file_path: file.clone(),
                    start_line: line_number,
                    end_line: line_number,
                    language: language.clone(),
                    symbols: Vec::new(),
                    breadcrumbs: Vec::new(),
                },
                score: 0.5 / (rank + 1) as f32,
                source: SearchMode::Bm25,
                explanation: None,
            });
        }
    }
}

