fn normalize_filter_path(path: &str) -> String {
    let normalized = path.replace('\\', "/");
    let mut parts = Vec::new();
    for part in normalized.split('/') {
        match part {
            "" | "." => {}
            ".." => {
                if parts.last().is_some_and(|segment| *segment != "..") {
                    parts.pop();
                } else {
                    parts.push(part);
                }
            }
            value => parts.push(value),
        }
    }
    parts.join("/")

