}

fn extract_swift_symbol(trimmed: &str, line_number: usize) -> Option<Symbol> {
    let trimmed = strip_declaration_modifiers(trimmed);
    let (kind, rest) = if let Some(rest) = trimmed.strip_prefix("struct ") {
